import type {
  CommercialPresetRefreshRequest,
  CommercialPresetRefreshScope,
  FilterForm,
} from 'models/Filters';

import { COMMERCIAL_RESULTS_CROSS_FILTER_KEYS } from './constants';

export type CommercialResultsFormTier = 1 | 2 | 3;

const COMMERCIAL_TIER2_FLAT_FILTER_SKELETON_KEYS = [
  'region',
  'brands',
  'channel',
  'pack_type',
  'category',
  'non_alcoholic',
  'growth_levers',
  'beer_price_segment',
  'portfolios',
] as const;

const COMMERCIAL_TIER_DROP_TO_TIER1_SKELETON_KEYS = [
  ...COMMERCIAL_TIER2_FLAT_FILTER_SKELETON_KEYS,
  'sub_brands',
  'sku',
] as const;

const COMMERCIAL_BRAND_DEPENDENT_SKELETON_KEYS = [
  'region',
  'channel',
  'pack_type',
  'sub_brands',
  'sku',
] as const;

const COMMERCIAL_BRAND_TRIGGER_SKELETON_KEYS = [
  ...COMMERCIAL_BRAND_DEPENDENT_SKELETON_KEYS,
  ...COMMERCIAL_RESULTS_CROSS_FILTER_KEYS,
] as const;

const COMMERCIAL_V2_TRIGGER_SKELETON_KEYS = [
  'brands',
  ...COMMERCIAL_BRAND_DEPENDENT_SKELETON_KEYS,
  ...COMMERCIAL_RESULTS_CROSS_FILTER_KEYS,
] as const;

const COMMERCIAL_TIER_DRIVER_TRIGGER_FIELDS = new Set([
  'zone',
  'country',
  'brands',
]);

function isBrandTierDriverTrigger(triggerField?: string): boolean {
  return (
    triggerField !== undefined &&
    COMMERCIAL_TIER_DRIVER_TRIGGER_FIELDS.has(triggerField)
  );
}

function isV2Trigger(triggerField?: string): boolean {
  return COMMERCIAL_RESULTS_CROSS_FILTER_KEYS.includes(
    triggerField as (typeof COMMERCIAL_RESULTS_CROSS_FILTER_KEYS)[number],
  );
}

/**
 * Fields that show skeleton while a tiered preset refetch runs.
 * Brand/tier-driver changes skeleton geo + V2; V2 changes also block every
 * hierarchy dimension whose option catalog is recalculated by the backend.
 */
export function getCommercialPresetSkeletonFieldKeys(
  targetTier: CommercialResultsFormTier,
  previousTier?: CommercialResultsFormTier,
  triggerField?: string,
): string[] {
  const brandTriggered = isBrandTierDriverTrigger(triggerField);
  const v2Only = [...COMMERCIAL_RESULTS_CROSS_FILTER_KEYS];
  const brandScope = [...COMMERCIAL_BRAND_TRIGGER_SKELETON_KEYS];
  const v2Scope = [...COMMERCIAL_V2_TRIGGER_SKELETON_KEYS];

  if (targetTier === 3 && previousTier === 2) {
    return brandScope;
  }

  if (
    previousTier !== undefined &&
    previousTier === targetTier &&
    targetTier !== 1
  ) {
    if (brandTriggered) return brandScope;
    return isV2Trigger(triggerField) ? v2Scope : v2Only;
  }

  if (targetTier === 3) {
    return brandTriggered
      ? brandScope
      : [...COMMERCIAL_BRAND_DEPENDENT_SKELETON_KEYS];
  }

  if (targetTier === 2) {
    if (previousTier === 3) {
      return [...COMMERCIAL_BRAND_DEPENDENT_SKELETON_KEYS];
    }
    return [...COMMERCIAL_TIER2_FLAT_FILTER_SKELETON_KEYS];
  }

  if (previousTier === 2 || previousTier === 3) {
    return [...COMMERCIAL_TIER_DROP_TO_TIER1_SKELETON_KEYS];
  }

  return [];
}

/**
 * Skeleton fields when flat drivers (region/channel/pack_type) change within the same tier.
 */
export function getCommercialPresetSkeletonFieldKeysForFlatDriverChange(
  targetTier: CommercialResultsFormTier,
): string[] {
  if (targetTier === 3) {
    return [
      'brands',
      'region',
      'channel',
      'pack_type',
      'sub_brands',
      'sku',
      ...COMMERCIAL_RESULTS_CROSS_FILTER_KEYS,
    ];
  }

  if (targetTier === 2) {
    return [
      'brands',
      'region',
      'channel',
      'pack_type',
      ...COMMERCIAL_RESULTS_CROSS_FILTER_KEYS,
    ];
  }

  return [];
}

/**
 * Tier follows **form** (live drawer), aligned with BFF query composition.
 *
 * - Tier 1: global country (ABI) or unset.
 * - Tier 2: concrete country, brand still “open” (`All` / empty).
 * - Tier 3: concrete country + any other `brands` value.
 */
export function resolveCommercialResultsRefreshTier(
  form: FilterForm | undefined,
): CommercialResultsFormTier {
  const country = form?.country;
  const brand = form?.brands;

  const tier1 =
    country == null ||
    country === '' ||
    String(country).toUpperCase() === 'ABI';
  if (tier1) return 1;

  const brandAll =
    brand == null || brand === '' || String(brand).toUpperCase() === 'ALL';
  if (brandAll) return 2;

  return 3;
}

export function normalizeCommercialPresetRefreshRequest(
  arg: CommercialPresetRefreshRequest | undefined,
): {
  scope: CommercialPresetRefreshScope;
  triggerField?: string;
  urlNavigationCommit?: boolean;
} {
  if (arg === undefined || arg === 'form' || arg === 'applied') {
    return { scope: arg === 'applied' ? 'applied' : 'form' };
  }

  return {
    scope: arg.scope ?? 'form',
    triggerField: arg.triggerField,
    urlNavigationCommit: arg.urlNavigationCommit,
  };
}
